#include <WiFi.h>
#include <WebServer.h>

// Настройки WiFi - замените на свои
const char* WIFI_SSID = "YOUR_SSID";
const char* WIFI_PASS = "YOUR_PASSWORD";

// Пины (согласно схеме)
const int PIN_SENSE = D0; // щупы -> 100k подтяжка к 3V3, через 1k к разъему J_PROBE
const int PIN_BUZZER = D1; // активный зуммер C96127 (низкий уровень = звук, т.к. P1 на 3V3)
const int PIN_LED = D2;    // красный LED
const int PIN_BUTTON = D10; // кнопка SW1 к GND, INPUT_PULLUP

WebServer server(80);
bool leakDetected = false;
bool muted = false;
unsigned long lastRead = 0;
unsigned long lastAlarm = 0;

void handleRoot(){
  String html = "<!DOCTYPE html><html><head><meta charset=utf-8><meta name='viewport' content='width=device-width,initial-scale=1'>";
  html += "<title>Датчик протечки</title>";
  html += "<meta http-equiv='refresh' content='5'>";
  html += "<style>body{font-family:sans-serif;text-align:center;padding:20px} .ok{color:green} .alarm{color:red;font-size:1.5em;animation:blink 1s infinite} @keyframes blink{50%{opacity:0}} button{padding:12px 24px;font-size:16px}</style></head><body>";
  html += "<h1>💧 Датчик протечки воды</h1>";
  if(leakDetected) html += "<p class='alarm'>🚨 ПРОТЕЧКА ОБНАРУЖЕНА!</p>";
  else html += "<p class='ok'>✅ Сухо — протечек нет</p>";
  html += "<p>Зуммер: " + String((leakDetected && !muted)?"ВКЛ":"ВЫКЛ") + " | Приглушен: " + String(muted?"Да":"Нет") + "</p>";
  html += "<p><a href='/mute'><button>" + String(muted?"Включить звук":"Приглушить") + "</button></a> <a href='/test'><button>Тест сирены</button></a></p>";
  html += "<p>IP: " + WiFi.localIP().toString() + " | Uptime: " + String(millis()/1000) + "c</p>";
  html += "</body></html>";
  server.send(200,"text/html",html);
}
void handleApi(){
  String j = "{\"leak\":" + String(leakDetected?"true":"false") + ",\"muted\":" + String(muted?"true":"false") + ",\"buzzer\":" + String((leakDetected && !muted)?"true":"false") + "}";
  server.send(200,"application/json",j);
}
void handleMute(){ muted=!muted; server.sendHeader("Location","/"); server.send(303);}
void handleTest(){ // короткий тест 1 сек
  digitalWrite(PIN_BUZZER, LOW); digitalWrite(PIN_LED, HIGH); delay(1000);
  digitalWrite(PIN_BUZZER, HIGH); digitalWrite(PIN_LED, LOW);
  server.sendHeader("Location","/"); server.send(303);
}

void setup(){
  pinMode(PIN_SENSE, INPUT); // внешняя подтяжка 100k к 3.3В, вода стягивает к GND
  pinMode(PIN_BUZZER, OUTPUT); digitalWrite(PIN_BUZZER, HIGH); // выкл (активный зуммер: HIGH=тишина)
  pinMode(PIN_LED, OUTPUT); digitalWrite(PIN_LED, LOW);
  pinMode(PIN_BUTTON, INPUT_PULLUP);

  Serial.begin(115200);
  delay(300);
  Serial.println("Leak detector start");

  WiFi.begin(WIFI_SSID, WIFI_PASS);
  unsigned long t0=millis();
  while(WiFi.status()!=WL_CONNECTED && millis()-t0<15000) delay(500);
  if(WiFi.status()==WL_CONNECTED) Serial.println(WiFi.localIP());
  else Serial.println("WiFi not connected - работа автономно");

  server.on("/", handleRoot);
  server.on("/api", handleApi);
  server.on("/mute", handleMute);
  server.on("/test", handleTest);
  server.begin();
}

void loop(){
  server.handleClient();

  // опрос датчика с антидребезгом: вода = низкий уровень (сопротивление воды ~10-100к замыкает на GND)
  bool raw = (digitalRead(PIN_SENSE)==LOW); // LOW = вода
  // простой фильтр: считаем протечкой если 3 подряд чтения LOW с интервалом 50мс
  static uint8_t cnt=0;
  if(millis()-lastRead>50){
    lastRead=millis();
    if(raw) { if(cnt<10) cnt++; } else { if(cnt>0) cnt--; }
    bool newLeak = (cnt>=3);
    if(newLeak != leakDetected){
      leakDetected = newLeak;
      if(leakDetected) { muted=false; Serial.println("LEAK!"); }
      else Serial.println("DRY");
    }
  }

  // управление сиреной и LED
  if(leakDetected && !muted){
    // прерывистый сигнал 0.5с вкл / 0.5с выкл
    bool on = (millis()%1000 < 500);
    digitalWrite(PIN_BUZZER, on?LOW:HIGH);
    digitalWrite(PIN_LED, on?HIGH:LOW);
  } else {
    digitalWrite(PIN_BUZZER, HIGH);
    digitalWrite(PIN_LED, LOW);
  }

  // кнопка: короткое нажатие - приглушить/снять, длинное 3с - тест
  static unsigned long pressStart=0;
  if(digitalRead(PIN_BUTTON)==LOW){
    if(pressStart==0) pressStart=millis();
    if(millis()-pressStart>2000 && millis()-lastAlarm>3000){
      lastAlarm=millis();
      // тест
      digitalWrite(PIN_BUZZER, LOW); delay(200); digitalWrite(PIN_BUZZER, HIGH);
    }
  } else {
    if(pressStart!=0 && millis()-pressStart<1000){
      // короткое нажатие
      if(leakDetected) muted=!muted;
      delay(200);
    }
    pressStart=0;
  }
}
